import '../../src/styles/index.css';import '../../src/styles/atelier.css';
import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {UIProvider} from '../../src/context/UIContext.jsx';import GaleriPanel from '../../src/components/GaleriPanel.jsx';import Button from '../../src/components/ui/Button.jsx';import {api} from '../../src/api/client.js';import {useAutoSave} from '../../src/hooks/useAutoSave.js';
let failOnce=false;
api.defaults.adapter=async config=>{if(config.method==='get')return {config,status:200,statusText:'OK',headers:{},data:{media:[],maxGallery:10}};await new Promise(resolve=>setTimeout(resolve,1000));if(failOnce){failOnce=false;throw Object.assign(new Error('QA'),{config,response:{status:500,data:{error:'Gagal menyimpan pada simulasi uji.'}}})}const payload=JSON.parse(config.data||'{}');return {config,status:200,statusText:'OK',headers:{},data:{themeSettings:payload}}};
const initial={id:'toast-status-qa',themeId:'garden-canvas',galleryMedia:[],themeSettings:{galleryLayout:'editorial'}};
function App(){const [inv,setInv]=useState(initial),[number,setNumber]=useState(0);const {schedule}=useAutoSave('toast-test',async v=>{await api.patch('/invitations/me/theme',v,{notification:false})},()=>setNumber(n=>n+1));return <div className="atelier-app" style={{padding:24,maxWidth:900}}><h1 style={{fontSize:30}}>Uji notifikasi · data contoh</h1><div style={{display:'flex',gap:12,margin:'16px 0'}}><Button variant="secondary" onClick={()=>{failOnce=true;schedule({typography:{bodyScale:1}})}}>Uji gagal dan coba lagi</Button><span>{number} autosave selesai</span></div><div className="panel" style={{maxWidth:500,background:'#faf8ef',padding:20}}><GaleriPanel invitation={inv} onUpdated={setInv}/></div><p style={{marginTop:500}}>Akhir panel — toast tetap terlihat di atas layar.</p></div>}
createRoot(document.getElementById('root')).render(<UIProvider><App/></UIProvider>);
